 15	    align-items: center;
 16	    min-height: 100vh;
 17	}
 18	
 19	.container {
 20	    background-color: white;
 21	    border-radius: 10px;
 22	    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
 23	    padding: 30px;
 24	    width: 90%;
 25	    max-width: 900px;
 26	}
 27	
 28	h1 {
 29	    text-align: center;
 30	    margin-bottom: 15px;
 31	    color: #2c3e50;
 32	}
 33	
 34	p {
 35	    text-align: center;
 36	    margin-bottom: 20px;
 37	    color: #7f8c8d;
 38	}
 39	
 40	.controls {
 41	    display: flex;
 42	    flex-direction: column;
 43	    gap: 15px;
 44	    margin-bottom: 25px;
 45	}
 46	
 47	#user-select {
 48	    padding: 12px;
 49	    border: 1px solid #ddd;
 50	    border-radius: 5px;
 51	    font-size: 16px;
 52	    background-color: #f9f9f9;
 53	    transition: border-color 0.3s;
 54	}
 55	
 56	#user-select:focus {
 57	    border-color: #3498db;
 58	    outline: none;
 59	}
 60	
 61	#recommend-btn {
 62	    padding: 12px 20px;
 63	    background-color: #3498db;
 64	    color: white;
 65	    border: none;
 66	    border-radius: 5px;
 67	    font-size: 16px;
 68	    cursor: pointer;
 69	    transition: background-color 0.3s;
 70	}
 71	
 72	#recommend-btn:hover {
 73	    background-color: #2980b9;
 74	}
 75	
 76	#result-box {
 77	    display: grid;
 78	    grid-template-columns: 1fr 1fr;
 79	    gap: 15px;
 80	}
 81	
 82	.result-column {
 83	    background-color: #f8f9fa;
 84	    padding: 20px;
 85	    border-radius: 5px;
 86	    border-left: 4px solid #3498db;
 87	}
 88	
 89	.result-column h2 {
 90	    font-size: 1.05rem;
 91	    color: #2c3e50;
 92	    margin-bottom: 10px;
 93	    text-align: left;
 94	}
 95	
 96	.result-column p,
 97	.result-column ul {
 98	    text-align: left;
 99	    color: #2c3e50;
100	    margin: 0;
101	}
102	
103	.result-column ul {
104	    padding-left: 20px;
105	}
106	
107	@media (max-width: 640px) {
108	    #result-box {
109	        grid-template-columns: 1fr;
110	    }
111	}
