// Missing-value strategy: co-rated entries only. A zero marks an unrated
// user-movie pair, so it never contributes to the dot product or either norm.
// The co-rated count is diagnostic only; it does not weight the similarity.

// Initialize the application when the window loads
window.onload = async function() {
    const userBased = document.getElementById('user-based-result');
    const itemBased = document.getElementById('item-based-result');

    try {
        userBased.innerHTML = '<p>Loading movie data...</p>';
        itemBased.innerHTML = '<p>Loading movie data...</p>';

        await loadData();

        populateUserDropdown();

        userBased.innerHTML = '<p>Data loaded. Select a user.</p>';
        itemBased.innerHTML = '<p>Data loaded. Select a user.</p>';
    } catch (error) {
        console.error('Initialization error:', error);
        // The error message is already shown by data.js
    }
};

// Populate the user dropdown with one option per user id found in u.data
function populateUserDropdown() {
    const selectElement = document.getElementById('user-select');

    // Clear existing options except the first placeholder
    while (selectElement.options.length > 1) {
        selectElement.remove(1);
    }

    for (let userId = 1; userId <= numUsers; userId++) {
        const option = document.createElement('option');
        option.value = userId;
        option.textContent = `User ${userId}`;
        selectElement.appendChild(option);
    }
}

// Return the count as a separate diagnostic without changing the similarity API.
function cosineSimilarityDetails(a, b) {
    let dot = 0;
    let normA = 0;
    let normB = 0;
    let coRatedCount = 0;

    for (let index = 0; index < a.length; index++) {
        if (a[index] === 0 || b[index] === 0) continue;

        dot += a[index] * b[index];
        normA += a[index] * a[index];
        normB += b[index] * b[index];
        coRatedCount++;
    }

    const denominator = Math.sqrt(normA * normB);
    return {
        similarity: coRatedCount > 0 && denominator > 0 ? dot / denominator : 0,
        coRatedCount
    };
}

function cosineSimilarity(a, b) {
    return cosineSimilarityDetails(a, b).similarity;
}

function getUserBasedRecommendations(activeUserId, topK = 5) {
    const activeRatings = ratingMatrix[activeUserId];
    const neighbors = [];

    for (let userId = 1; userId <= numUsers; userId++) {
        if (userId === activeUserId) continue;
        const similarity = cosineSimilarity(activeRatings, ratingMatrix[userId]);
        if (similarity > 0) neighbors.push({ userId, similarity });
    }

    neighbors.sort((a, b) => b.similarity - a.similarity || a.userId - b.userId);
    const closestNeighbors = neighbors.slice(0, 20);
    const candidates = [];

    for (let movieId = 1; movieId <= numMovies; movieId++) {
        if (activeRatings[movieId] !== 0) continue;

        let weightedRatings = 0;
        let similaritySum = 0;
        for (const { userId, similarity } of closestNeighbors) {
            const rating = ratingMatrix[userId][movieId];
            if (rating === 0) continue;
            weightedRatings += similarity * rating;
            similaritySum += similarity;
        }

        if (similaritySum > 0) {
            candidates.push({ movieId, score: weightedRatings / similaritySum });
        }
    }

    return topRecommendations(candidates, topK);
}

function getItemBasedRecommendations(activeUserId, topK = 5) {
    const activeRatings = ratingMatrix[activeUserId];
    const ratedMovieIds = [];
    const unseenMovieIds = [];
    for (let movieId = 1; movieId <= numMovies; movieId++) {
        if (activeRatings[movieId] === 0) unseenMovieIds.push(movieId);
        else ratedMovieIds.push(movieId);
    }

    // Transpose once so each cosine call receives an item rating column.
    const itemVectors = Array.from({ length: numMovies + 1 }, (_, movieId) =>
        ratingMatrix.map(userRatings => userRatings[movieId])
    );
    const candidates = [];

    for (const movieId of unseenMovieIds) {
        let weightedRatings = 0;
        let similaritySum = 0;
        for (const ratedMovieId of ratedMovieIds) {
            const similarity = cosineSimilarity(itemVectors[movieId], itemVectors[ratedMovieId]);
            if (similarity <= 0) continue;
            weightedRatings += similarity * activeRatings[ratedMovieId];
            similaritySum += similarity;
        }

        if (similaritySum > 0) {
            candidates.push({ movieId, score: weightedRatings / similaritySum });
        }
    }

    return topRecommendations(candidates, topK);
}

function topRecommendations(candidates, topK) {
    candidates.sort((a, b) => b.score - a.score || a.movieId - b.movieId);
    return candidates.slice(0, topK).map(({ movieId, score }) => ({
        title: movies[movieId - 1].title,
        score
    }));
}

// Provided — read the selected user and render both recommendation lists
function getRecommendations() {
    const selectElement = document.getElementById('user-select');
    const userId = parseInt(selectElement.value, 10);

    if (isNaN(userId)) {
        renderList('user-based-result', [], 'Please select a user first.');
        renderList('item-based-result', [], 'Please select a user first.');
        return;
    }

    renderList('user-based-result', getUserBasedRecommendations(userId));
    renderList('item-based-result', getItemBasedRecommendations(userId));
}

// Provided — render a list of { title, score } into the given element
function renderList(elementId, items, message) {
    const el = document.getElementById(elementId);

    if (message) {
        el.innerHTML = `<p>${message}</p>`;
        return;
    }

    if (!items || items.length === 0) {
        el.innerHTML = '<p>No recommendations. (Implement the TODO above.)</p>';
        return;
    }

    const entries = items
        .map(item => `<li>${item.title} &mdash; ${Number(item.score).toFixed(3)}</li>`)
        .join('');
    el.innerHTML = `<ul>${entries}</ul>`;
}
// Global variables for storing movie and rating data
let movies = [];
let ratings = [];

// Collaborative filtering structures (populated by buildRatingMatrix)
let numUsers = 0;          // highest user id found in u.data
let numMovies = 0;         // number of parsed movies
let ratingMatrix = null;   // (numUsers + 1) x (numMovies + 1); 0 = "not rated"

// Genre names as defined in the u.item file
const genreNames = [
    "unknown", "Action", "Adventure", "Animation", "Children's", "Comedy",
    "Crime", "Documentary", "Drama", "Fantasy", "Film-Noir",
    "Horror", "Musical", "Mystery", "Romance", "Sci-Fi",
    "Thriller", "War", "Western"
];

// Primary function to load data from files
async function loadData() {
    try {
        // Load and parse movie data
        const moviesResponse = await fetch('u.item');
        if (!moviesResponse.ok) {
            throw new Error(`Failed to load movie data: ${moviesResponse.status}`);
        }
        const moviesText = await moviesResponse.text();
        parseItemData(moviesText);

        // Load and parse rating data
        const ratingsResponse = await fetch('u.data');
        if (!ratingsResponse.ok) {
            throw new Error(`Failed to load rating data: ${ratingsResponse.status}`);
        }
        const ratingsText = await ratingsResponse.text();
        parseRatingData(ratingsText);

        // Derive matrix dimensions, then build the rating matrix
        numUsers = ratings.reduce((max, r) => Math.max(max, r.userId), 0);
        numMovies = movies.length;
        buildRatingMatrix();
    } catch (error) {
        console.error('Error loading data:', error);
        const errorTarget = document.getElementById('user-based-result');
        if (errorTarget) {
            errorTarget.innerHTML = `<p class="error">Error: ${error.message}. Please make sure u.item and u.data are in the correct location.</p>`;
        }
        throw error; // Re-throw so script.js can handle the error
    }
}

// Parse movie data from u.item format
function parseItemData(text) {
    const lines = text.split('\n');

    for (const line of lines) {
        if (line.trim() === '') continue;

        const fields = line.split('|');
        if (fields.length < 5) continue; // Skip invalid lines

        const id = parseInt(fields[0]);
        const title = fields[1];

        // Extract genres (last 19 fields)
        const genreValues = fields.slice(5, 24).map(value => parseInt(value));
        const genres = genreNames.filter((_, index) => genreValues[index] === 1);

        movies.push({ id, title, genres });
    }
}

// Parse rating data from u.data format
function parseRatingData(text) {
    const lines = text.split('\n');

    for (const line of lines) {
        if (line.trim() === '') continue;

        const fields = line.split('\t');
        if (fields.length < 4) continue; // Skip invalid lines

        const userId = parseInt(fields[0]);
        const itemId = parseInt(fields[1]);
        const rating = parseFloat(fields[2]);
        const timestamp = parseInt(fields[3]);

        ratings.push({ userId, itemId, rating, timestamp });
    }
}

// Index by raw IDs. Zero means "unrated"; observed MovieLens ratings are 1-5.
function buildRatingMatrix() {
    ratingMatrix = Array.from(
        { length: numUsers + 1 },
        () => Array(numMovies + 1).fill(0)
    );

    for (const { userId, itemId, rating } of ratings) {
        ratingMatrix[userId][itemId] = rating;
    }
}
