evaluate(`numUsers = 4; numMovies = 4;
    movies = [1,2,3,4].map(id => ({id, title: 'Movie ' + id}));
    ratings = [
        [1,1,5], [1,2,1],
        [2,1,5], [2,2,1], [2,3,4],
