// Initialize the application when the window loads
window.onload = async function() {
    try {
        // Display loading message
        const resultElement = document.getElementById('result');
        resultElement.textContent = "Loading movie data...";
        resultElement.className = 'loading';

        // Load data
        await loadData();

        // Populate dropdown and update status
        populateMoviesDropdowns();
        synchronizeActiveMovieSelectors();
        resultElement.textContent = "Data loaded. Please select a movie.";
        resultElement.className = 'success';
    } catch (error) {
        console.error('Initialization error:', error);
        // Error message already set in data.js
    }
};

// Populate the movies dropdown with sorted movie titles
function populateMoviesDropdowns() {
    // Sort movies alphabetically by title
    const sortedMovies = [...movies].sort((a, b) => a.title.localeCompare(b.title));
    const selectIds = ['movie-select', 'profile-select-1', 'profile-select-2', 'profile-select-3'];

    selectIds.forEach(selectId => {
        const selectElement = document.getElementById(selectId);
        while (selectElement.options.length > 1) {
            selectElement.remove(1);
        }

        sortedMovies.forEach(movie => {
            const option = document.createElement('option');
            option.value = movie.id;
            option.textContent = movie.title;
            selectElement.appendChild(option);
        });
    });
}

// Keep the single active movie aligned with Movie 1 in the profile comparison
function synchronizeActiveMovieSelectors() {
    const activeMovieSelect = document.getElementById('movie-select');
    const profileMovieOneSelect = document.getElementById('profile-select-1');

    activeMovieSelect.addEventListener('change', () => {
        profileMovieOneSelect.value = activeMovieSelect.value;
    });
    profileMovieOneSelect.addEventListener('change', () => {
        activeMovieSelect.value = profileMovieOneSelect.value;
    });
}

// Calculate cosine similarity between two numeric feature vectors
function cosineSimilarity(vectorA, vectorB) {
    const dotProduct = vectorA.reduce(
        (sum, value, index) => sum + value * vectorB[index],
        0
    );
    const normA = Math.sqrt(vectorA.reduce((sum, value) => sum + value * value, 0));
    const normB = Math.sqrt(vectorB.reduce((sum, value) => sum + value * value, 0));

    return normA > 0 && normB > 0 ? dotProduct / (normA * normB) : 0;
}

// Score candidates and preserve source order when cosine scores tie
function rankMovies(queryVector, excludedMovieIds, vectorProperty = 'genreVector') {
    return movies
        .filter(movie => !excludedMovieIds.has(movie.id))
        .map(candidate => ({
            ...candidate,
            score: cosineSimilarity(queryVector, candidate[vectorProperty])
        }))
        .sort((a, b) => {
            const difference = b.score - a.score;
            return Math.abs(difference) > 1e-12 ? difference : 0;
        })
        .slice(0, 5);
}

function getFeatureMode() {
    const useIdf = document.getElementById('feature-mode').value === 'idf';
    return {
        label: useIdf ? 'Experimental IDF-weighted cosine' : 'Binary cosine',
        vectorProperty: useIdf ? 'weightedGenreVector' : 'genreVector'
    };
}

function formatRecommendations(recommendations) {
    return recommendations
        .map(movie => `${movie.title} (${movie.score.toFixed(3)})`)
        .join(', ');
}

// Main recommendation function
function getRecommendations() {
    const resultElement = document.getElementById('result');

    try {
        // Step 1: Get user input
        const selectElement = document.getElementById('movie-select');
        const selectedMovieId = parseInt(selectElement.value);

        if (isNaN(selectedMovieId)) {
            resultElement.textContent = "Please select a movie first.";
            resultElement.className = 'error';
            return;
        }

        // Step 2: Find the liked movie
        const likedMovie = movies.find(movie => movie.id === selectedMovieId);
        if (!likedMovie) {
            resultElement.textContent = "Error: Selected movie not found in database.";
            resultElement.className = 'error';
            return;
        }

        // Show loading message while processing
        resultElement.textContent = "Calculating recommendations...";
        resultElement.className = 'loading';

        // Use setTimeout to allow the UI to update before heavy computation
        setTimeout(() => {
            try {
                const featureMode = getFeatureMode();
                const topRecommendations = rankMovies(
                    likedMovie[featureMode.vectorProperty],
                    new Set([likedMovie.id]),
                    featureMode.vectorProperty
                );

                // Step 7: Display results
                if (topRecommendations.length > 0) {
                    resultElement.textContent = `${featureMode.label} — because you liked "${likedMovie.title}", we recommend: ${formatRecommendations(topRecommendations)}`;
                    resultElement.className = 'success';
                } else {
                    resultElement.textContent = `No recommendations found for "${likedMovie.title}".`;
                    resultElement.className = 'error';
                }
            } catch (error) {
                console.error('Error in recommendation calculation:', error);
                resultElement.textContent = "An error occurred while calculating recommendations.";
                resultElement.className = 'error';
            }
        }, 100);
    } catch (error) {
        console.error('Error in getRecommendations:', error);
        resultElement.textContent = "An unexpected error occurred.";
        resultElement.className = 'error';
    }
}

// Recommend from the element-wise average of exactly three watched movies
function getProfileRecommendations() {
    const resultElement = document.getElementById('profile-result');
    const selectedIds = [1, 2, 3].map(index =>
        parseInt(document.getElementById(`profile-select-${index}`).value)
    );

    if (selectedIds.some(id => isNaN(id)) || new Set(selectedIds).size !== 3) {
        resultElement.textContent = "Please select exactly three different watched movies.";
        resultElement.className = 'error';
        return;
    }

    const watchedMovies = selectedIds.map(id => movies.find(movie => movie.id === id));
    if (watchedMovies.some(movie => !movie)) {
        resultElement.textContent = "Error: A selected movie was not found.";
        resultElement.className = 'error';
        return;
    }

    const featureMode = getFeatureMode();
    const profileVector = genreNames.map((_, index) =>
        watchedMovies.reduce(
            (sum, movie) => sum + movie[featureMode.vectorProperty][index],
            0
        ) / 3
    );
    const topRecommendations = rankMovies(
        profileVector,
        new Set(selectedIds),
        featureMode.vectorProperty
    );

    resultElement.textContent = `${featureMode.label} — from your 3-movie profile, we recommend: ${formatRecommendations(topRecommendations)}`;
    resultElement.className = 'success';
}
# Week 2: Content-Based Movie Recommender

## Objective

Compare Top-5 recommendations from one active movie with recommendations from an aggregated three-movie profile, using MovieLens 100K genre features and cosine similarity.

## Run the app

From this directory, start a local server:

```bash
python3 -m http.server 8000
```

Then open `http://localhost:8000/`. The app loads `u.item` in the browser, so serving the directory is more portable than opening `index.html` directly.

## Required implementation

- Parses all 19 MovieLens genre fields with the corrected mapping, including `unknown` and `Western`.
- Represents each movie as a 19-dimensional binary genre vector.
- Uses zero-safe cosine similarity and returns five scored recommendations.
- Keeps the active movie out of item-to-item candidates.
- Builds the profile by averaging exactly three movie vectors element by element.
- Keeps all three watched movies out of profile candidates.
- Uses MovieLens source order as the deterministic tie-break after a `1e-12` score comparison.

The required default is **Binary genres — required cosine baseline**. The interface keeps both **Item-to-Item Cosine** and **3-Movie Profile Cosine** available for direct comparison.

## Experimental IDF improvement

The optional **IDF-weighted genres — experimental improvement** mode weights each genre by

```text
idf(g) = log((N + 1) / (df(g) + 1)) + 1
```

Movie vectors are weighted before cosine scoring; three-movie profiles average the weighted vectors. This mode is a controlled representation experiment, not part of the required binary-cosine baseline.

## Reproducible analysis

Scripts and their machine-readable and Markdown results are in `analysis/`:

- `audit_parser_impact.py` — impact of the original 18-label parser defect.
- `verify_genre_mapping.py` — corrected mapping checks.
- `verify_cosine_and_compare.py` — cosine arithmetic, Jaccard comparison, and overlap diagnostic.
- `verify_profile_and_compare.py` — profile arithmetic, real-user comparison, and catalog diagnostics.
- `audit_tie_sensitivity.py` — source-order versus seeded random tie-breaking.
- `audit_idf_weighting.py` — IDF arithmetic, discrimination, catalog, and paired tie-robustness checks.

Run any script from the repository root with `python3 path/to/script.py`. Each script uses the checked-in MovieLens files and fixed seeds where randomness is involved.

## Key verified findings

- Correcting the parser changed Top-2 membership for 83 of 1,682 seeds and Top-5 membership for 106 of 1,682 seeds under the original Jaccard setup.
- Corrected Jaccard and ordinary binary cosine produced different Top-5 membership for 1 of 1,682 item seeds; this is a catalog observation, not a relevance result.
- In the controlled 942-user comparison, ordered item/profile Top-5 lists differed for 833 users (88.4289%), with mean set-overlap fraction 0.18535.
- Binary genre vectors create large score-tie groups, and catalog popularity/coverage measurements are sensitive to tie-breaking.
- IDF weighting increased the mean number of distinct candidate scores from 10.01 to 85.88 for item queries and from 19.10 to 147.99 for profile queries, while reducing tie frequency in the measured setup.

## Limitations

The representation contains only 19 coarse genres. It does not use ratings as weights, recency weights, collaborative signals, text embeddings, or popularity reranking. The controlled comparisons measure ranking behavior and catalog diagnostics, not held-out relevance. Consequently, neither profile aggregation nor IDF weighting is claimed to improve recommendation quality. Exact/tolerance-level ties still exist, and deterministic source-order tie-breaking can affect membership at the Top-5 cutoff.
