.container {
    width: min(100%, 980px);
    margin: 24px auto;
    padding: clamp(22px, 4vw, 40px);
    background: #fff;
    border-radius: 14px;
    box-shadow: 0 10px 30px rgba(27, 55, 83, 0.1);
