.page-header { text-align: center; margin-bottom: 28px; }
h1, h2, h3, p { margin-top: 0; }
h1 { margin-bottom: 10px; color: #173b63; font-size: clamp(1.7rem, 3vw, 2.2rem); line-height: 1.2; }
h2 { margin-bottom: 14px; color: #173b63; font-size: 1.25rem; }
h3 { margin-bottom: 12px; color: #173b63; font-size: 1.05rem; }
