    min-height: 46px;
    padding: 10px 22px;
    border: 0;
    border-radius: 7px;
    background: #2478d4;
    color: white;
    font: inherit;
    font-weight: 700;
    cursor: pointer;
}

button:hover:not(:disabled) { background: #175fae; }
#predict-btn { display: block; min-width: 190px; margin: 18px auto 0; }

