assert.ok(dropdown.children.every(option => option.textContent.toLowerCase().includes('godfather')));
assert.equal(state('selectedMovieId'), null);
context.predictSelectedMovie();
assert.equal(status.textContent, 'Please select a movie from the matching results.');
const godfatherPartII = dropdown.children.find(option => option.dataset.movieId === '187');
assert.ok(godfatherPartII);
context.selectMovieResult({ target: godfatherPartII });
assert.equal(state('selectedMovieId'), 187);
assert.equal(input.value, 'Godfather: Part II, The (1974)');
assert.equal(dropdown.hidden, true);
context.predictSelectedMovie();
assert.equal(elements.get('user-prediction-result').children[0].textContent, '5.000');
assert.equal(elements.get('item-prediction-result').children[0].textContent, '3.717');

input.value = 'TaXi';
context.filterMovieDropdown();
assert.equal(state('selectedMovieId'), null);
assert.ok(dropdown.children.length > 0);
assert.ok(dropdown.children.every(option => option.textContent.toLowerCase().includes('taxi')));
key('ArrowDown');
assert.equal(key('Enter').prevented, true);
assert.ok(Number.isInteger(state('selectedMovieId')));

input.value = 'unfindable-movie-title-zzz';
context.filterMovieDropdown();
assert.equal(dropdown.children.length, 1);
assert.equal(dropdown.children[0].textContent, 'No matching unseen movies');
assert.equal(key('Enter').prevented, true);
assert.equal(status.textContent, 'Please select a movie from the matching results.');

userSelect.value = '3';
context.handleUserChange();
assert.equal(input.value, '');
assert.equal(state('selectedMovieId'), null);
assert.equal(dropdown.hidden, true);
assert.equal(input.getAttribute('aria-expanded'), 'false');
context.openMovieDropdown();
assertUnseenAndSorted(3);
console.log('Combobox checks passed: browse, A-Z, substring search, click/Enter/Arrow/Escape, ID selection, typed-text validation, no-match, user reset, unseen-only.');
